function InstanceDeactivateAI()
{

	// Carved out functions
	function IsUserMaint()
	{
		return gs.hasRole('maint');
	}	
	function GetStringValue(vInput)
	{
		if (vInput == undefined)
		{
			return '';
		}
		if (vInput == null)
		{
			return '';
		}
		return ''+vInput;
	}	
	function GetIntegerValue(vValue)
	{
		if (vValue === true)
		{
			return 1;
		}
		var vResult = parseInt(vValue);
		if (isNaN(vResult))
		{
			return 0;
		}
		return vResult;
	}
	function GetBoolValue(vInput)
	{
		if (vInput == undefined)
		{
			return false;
		}
		if (vInput == null)
		{
			return false;
		}
		if (vInput === true)
		{
			return true;
		}
		if (vInput == 'true')
		{
			return true;
		}
		if (vInput == 'false')
		{
			return false;
		}
		if (vInput == 'null')
		{
			return false;
		}
		if (vInput != 0)
		{
			return true;
		}
		return false;
	}
	function IsValidSysId(strSysId)
	{
		strSysId = GetStringValue(strSysId);

		var anomalies = GetSysIdAnomalies();
		var strTable = GetStringValue(GetValue(anomalies,strSysId));
		if (strTable != '')
		{
			return true;
		}
		if (strSysId.length == 3)
		{
			var grCurrency = new GlideRecord('fx_currency');
			grCurrency.addQuery('sys_id','=',strSysId);
			grCurrency.query();
			if (grCurrency.next() == true)
			{
				return true;
			}
			else
			{
				return false;
			}
		}
		if (strSysId.length != 32)
		{
			return false;
		}
		if (StringCheckRegEx(strSysId,'([0-9a-f]){32}') == false)
		{
			return false;
		}
		return true;
	}	
	function RenderValue(vValue, bHideEmpty, bUnsortedKeys, bCompactOutput, nLevel)
	{
		bHideEmpty = GetBoolValue(bHideEmpty);
		bUnsortedKeys = GetBoolValue(bUnsortedKeys);
		bCompactOutput = GetBoolValue(bCompactOutput);
		nLevel = GetIntegerValue(nLevel);
		var strLevel = '___';
		strLevel = strLevel.repeat(nLevel);

		if (vValue === undefined)
		{
			return 'undefined';
		}

		if (vValue === null)
		{
			return 'null';
		}

		var strType = GetType(vValue); 
		if (strType == 'JavaObject')
		{
			return ''+vValue;
		}	
		if (strType == 'ScopedGlideElement')
		{
			if (vValue.getDisplayValue() == '0')
			{
				return '0';
			}
			if (vValue.nil() == false)
			{
				return ''+vValue;
			}
			return vValue.getDisplayValue();
		}
		if (strType == 'function')
		{
			return '\n'+vValue;
		}
		if (strType == 'Array')
		{
			var strOutput = '';
			if (vValue.length == 0)
			{
				if (strLevel.length > 0)
				{
					strOutput += '\n';
				}
				strOutput += strLevel+'[]';
			}
			else
			{
				vValue.forEach( function(vElement,nKey)
				{
					strOutput += '\n'+strLevel+'['+nKey+']: '+RenderValue(vElement,bHideEmpty,bUnsortedKeys,bCompactOutput,nLevel+1);
				});
			}
			return strOutput;
		}
		if (strType == 'RegExp')
		{
			return ''+vValue;
		}	
		if (IsObject(vValue))
		{
			var bScopedGlideRecord = (GetType(vValue) == 'ScopedGlideRecord');
			var strOutput = '';

			if (bCompactOutput == true && IsExistingRecord(vValue))
			{
				return '\n'+strLevel+RenderRecordSummary(vValue);
			}

			var aKeys = GetKeys(vValue);
			//var aKeys = ['sys_id','short_description']; 
			if (aKeys.length == 0)
			{
				if (strLevel.length > 0)
				{
					strOutput += '\n';
				}		
				strOutput += strLevel+'{}';
			}
			else
			{
				function Compare(value1, value2)
				{
					if (value1 < value2)
					{
						return -1;
					}
					if (value1 > value2)
					{
						return 1;
					}
					return 0;
				}
				function CompareUnderscoresAtEnd(value1, value2)
				{
					value1 = GetStringValue(value1);
					value2 = GetStringValue(value2);
					var nUnderscores1 = 0;
					var nUnderscores2 = 0;
					while (value1[nUnderscores1] == '_')
					{
						nUnderscores1++;
					}
					while (value2[nUnderscores2] == '_')
					{
						nUnderscores2++;
					}
					if (nUnderscores1 < nUnderscores2)
					{
						return -1;
					}
					if (nUnderscores1 > nUnderscores2)
					{
						return 1;
					}
					return Compare(value1, value2);
				}

				function CompareGlideRecordKeys(str1, str2)
				{
					var aPriorityKeys = ['user_name','name','short_description'];
					for (var nKey = 0; nKey < aPriorityKeys.length; nKey++)
					{
						if (str1 == aPriorityKeys[nKey])
						{
							return -1
						}
						if (str2 == aPriorityKeys[nKey])
						{
							return 1;
						}
					}
					return CompareUnderscoresAtEnd(str1,str2);
				}		

				if (IsValidRecord(vValue))
				{
					var strTable = vValue.getRecordClassName();
					var strSysId = GetStringValue(vValue.sys_id);
					var strNumber = GetStringValue(vValue.getValue('number'));
					if (strTable != '')
					{
						strOutput += '\n'+strLevel+strTable+':';
						if (strNumber != '')
						{
							strOutput += ' '+strNumber+':';
						}
						if (strSysId != '')
						{
							strOutput += ' '+strSysId+':';
						}
					}
					if (bUnsortedKeys == false)
					{
						aKeys.sort(CompareGlideRecordKeys);
					}
				}
				else if (ArrayValueExists(GetKeys(vValue),'sys_id') == true)
				{
					var strClassName = GetStringValue(GetValue(vValue,'sys_class_name'));
					var strSysId = GetStringValue(GetValue(vValue,'sys_id'));
					var strNumber = GetStringValue(GetValue(vValue,'number'));

					if (   strClassName != ''
						|| strSysId != ''
						|| strNumber != '')
					{
						strOutput += '\n'+strLevel;
						if (strClassName != '')
						{
							strOutput += strClassName+': ';
						}
						if (strNumber != '')
						{
							strOutput += strNumber+': ';
						}
						if (strSysId != '')
						{
							strOutput += strSysId+': ';
						}
					}
					if (bUnsortedKeys == false)
					{
						aKeys.sort(CompareGlideRecordKeys);
					}
				}
				else
				{
					if (bUnsortedKeys == false)
					{
						aKeys.sort(CompareUnderscoresAtEnd);
					}
				}
				aKeys.forEach( function(strKey)
				{
					if (strKey == 'sys_meta' && bScopedGlideRecord)
					{
						var strValue = RenderValue(vValue.getValue(strKey),bHideEmpty,bUnsortedKeys,bCompactOutput,nLevel+1);	
					}
					else
					{
						var strValue = RenderValue(vValue[strKey],bHideEmpty,bUnsortedKeys,bCompactOutput,nLevel+1);
					}
					if (bHideEmpty == false || strValue != '')
					{
						strOutput += '\n'+strLevel+'["'+strKey+'"]: '+strValue;
					}
				});
			}
			return strOutput;
		}

		return ''+vValue;
	}
	function PrepareLogInfo(vPayload)
	{
		return RenderValue(vPayload);
	}
	function Log(vPayload)
	{
		gs.info(PrepareLogInfo(vPayload));
	}
	function GlideRecordSetValue(grRecord,strField,strValue)
	{
		if (IsValidRecord(grRecord) == false)
		{
			return false;
		}
		if (strField == 'sys_id')
		{
			if (grRecord.isNewRecord() != true)
			{
				return false;
			}
			grRecord.setNewGuidValue(strValue);
		}
		else
		{
			if (strValue == null)
			{
				strValue = '';
			}
			grRecord.setValue(strField,strValue);
		}
		return true;
	}	
	function SetProperty(strName, strValue, bAdd)
	{
		if (strName == false)
		{
			return false;
		}

		strName = GetStringValue(strName);
		strValue = GetStringValue(strValue);
		bAdd = GetBoolValue(bAdd);

		if (strName == '')
		{
			return false;
		}

		if (bAdd == true)
		{
			var vResult = RecordQueryOrInsert(
				'sys_properties',
				{
					name: strName,
					sys_scope: GetScopeSysIdFromPropertyName(strName)
				}, 
				{
					value: strValue
				}, true);
			if (vResult == false)
			{
				return false;
			}
			return true;
		}

		var grProp = new GlideRecord('sys_properties');
		grProp.addQuery('name','=',strName);
		grProp.query();
		if (grProp.next() == false)
		{
			return false;
		}
		GlideRecordSetValue(grProp,'value',strValue);
		var vResult = GlideRecordUpdate(grProp);
		if (IsValidSysId(vResult) == false)
		{
			return false;
		}
		return true;
	}	
	function GlideRecordUpdate(grRecord)
	{
		gs.info(x_snc_devtools.RenderRecordSummary(grRecord));
		//grRecord.update();
	}


	if (IsUserMaint() == false)
	{
		LogError('InstanceDeactivateAI requires "maint" access!');
		return false;
	}



	Log('InstanceDeactivateAI: START');


	Log('InstanceDeactivateAI: Removing urls from LLMGateway, LLMProxy, MLPredictor-Triton services...');
	var aLLMServices = ['LLMGateway','LLMProxy','MLPredictor-Triton'];
	var strEncodedQuery = 'nameIN' + GetStringValue(aLLMServices);

	var aServicesSysIds = [];
	var grSS = new GlideRecord('sys_service');
	grSS.addEncodedQuery(strEncodedQuery);
	grSS.query();
	while (grSS.next() == true)
	{
		aServicesSysIds.push(GetStringValue(grSS.sys_id));
	}

	var grSSE = new GlideRecord('sys_service_endpoint');
	grSSE.addQuery('service','IN',GetStringValue(aServicesSysIds));
	grSSE.query();
	while (grSSE.next() == true)
	{
		grSSE.url = '';
		GlideRecordUpdate(grSSE);
		Log('InstanceDeactivateAI: ' + RenderRecordSummary(grSSE));

	}

	Log('InstanceDeactivateAI: Removing url from Now LLM http connection...');

	var grConnection = new GlideRecord('http_connection');
	grConnection.addQuery('name','=','Now LLM');
	grConnection.query();

	while (grConnection.next() == true)
	{
		grConnection.connection_url = '';
		grConnection.host = '';
		GlideRecordUpdate(grConnection);
		Log('InstanceDeactivateAI: ' + RenderRecordSummary(grConnection));
	}

	Log('InstanceDeactivateAI: Deactivating Now Assist Deployments...');
	var grNAD = new GlideRecord('sys_now_assist_deployment');
	grNAD.addActiveQuery();
	grNAD.query();
	while (grNAD.next())
	{
		grNAD.active = false;
		GlideRecordUpdate(grNAD);
		Log('InstanceDeactivateAI: ' + RenderRecordSummary(grNAD));
	}

	Log('InstanceDeactivateAI: Deactivating all AI Agents...');
	var grAgents = new GlideRecord('sn_aia_agent_config');
	grAgents.addActiveQuery();
	grAgents.query();
	while (grAgents.next())
	{
		grAgents.active = false;
		GlideRecordUpdate(grAgents);
		Log('InstanceDeactivateAI: ' + RenderRecordSummary(grAgents));
	}


	Log('InstanceDeactivateAI: Deactivating all AI Skills...');
	var grSkills = new GlideRecord('sys_one_extend_capability');
	grSkills.addActiveQuery();
	grSkills.addQuery('type','=','skill');
	grSkills.query();
	while (grSkills.next())
	{
		grSkills.active = false;
		GlideRecordUpdate(grSkills);
		Log('InstanceDeactivateAI: ' + RenderRecordSummary(grSkills));
	}


	Log('InstanceDeactivateAI: Deactivating all OneExtend Definition Configs...');

	var grOEDC = new GlideRecord('sys_one_extend_definition_config');
	grOEDC.addActiveQuery();
	grOEDC.query();
	while (grOEDC.next())
	{
		grOEDC.active = false;
		GlideRecordUpdate(grOEDC,true);
		Log('InstanceDeactivateAI: ' + RenderRecordSummary(grOEDC));
	}

	Log('InstanceDeactivateAI: Deactivating Now Assist Code capabilities...');

	SetProperty('sn_now_assist_code.enable_code_assist','false');
    SetProperty('sn_now_assist_code.enable_auto_complete','false');
    SetProperty('sn_now_assist_code.enable_prompt_modal','false');
    SetProperty('sn_now_assist_code.enable_promptless_experience','false');

	Log('InstanceDeactivateAI: END');

	return true;
}
